witness.command:
mkdir -p /tmp/bench-witness && python3 -m coverage json --data-file="${COVERAGE_FILE:-/tmp/bench-witness/.coverage}" -o /tmp/bench-witness/coverage.json -q || { echo "WITNESS-UNAVAILABLE coverage json failed for data file ${COVERAGE_FILE:-/tmp/bench-witness/.coverage}"; exit 0; }; python3 -c "import ast, json, os, sys
cj, root = sys.argv[1], sys.argv[2]
wanted = sys.argv[3:]
try:
    data = json.load(open(cj))
except Exception as exc:
    print('WITNESS-UNAVAILABLE cannot read coverage json: %r' % (exc,)); raise SystemExit(0)
files = data.get('files') or {}
if not files:
    print('WITNESS-UNAVAILABLE coverage report contains no files'); raise SystemExit(0)
out = []
for want in wanted:
    hit = None
    for measured, info in files.items():
        norm = measured.replace(chr(92), '/')
        if norm == want or norm.endswith('/' + want):
            hit = info; break
    if hit is None:
        continue
    src_path = os.path.join(root, want)
    try:
        src = open(src_path, encoding='utf-8').read()
    except Exception as exc:
        print('WITNESS-UNAVAILABLE cannot read source %s: %r' % (src_path, exc)); raise SystemExit(0)
    spans = []
    def walk(node, prefix):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, ast.ClassDef):
                walk(child, prefix + child.name + '.')
            elif isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                spans.append((child.body[0].lineno, child.end_lineno, prefix + child.name))
                walk(child, prefix + child.name + '.')
            else:
                walk(child, prefix)
    walk(ast.parse(src), '')
    for line in hit.get('executed_lines') or []:
        best = None
        for lo, hi, name in spans:
            if lo <= line <= hi and (best is None or lo > best[0]):
                best = (lo, name)
        if best is not None:
            out.append(want + '::' + best[1])
for target in sorted(set(out)):
    print('COVERED ' + target)" /tmp/bench-witness/coverage.json /build aiohttp/http_parser.py
